const cfg = $('Config').first().json;
const asOf = new Date(cfg.as_of);
if (isNaN(asOf.getTime())) throw new Error("as_of is not a valid date: " + cfg.as_of);
const DAY = 86400000;
// Channels that take about a week are best effort: we do not wait for them.
const BEST_EFFORT = ["CHATGPT_SEARCH", "FOURSQUARE"];
const BUFFER_DAYS = 1;          // safety day on top of the slowest main channel
const FIRST_CONTACT_DAYS = 14;  // first message this many days before the deadline
const REMIND_AFTER_DAYS = 4;    // one reminder this many days after the first message...
const REMIND_LATEST_DAYS = 2;   // ...but at the latest this many days before the deadline
const rows = name => $(name).all().map(i => i.json).filter(r => r && r.bundle_id);
const only = (Array.isArray(cfg.bundle_ids) ? cfg.bundle_ids : []).map(String);
const itemsBy = {};
rows('Get Items').forEach(i => { (itemsBy[i.bundle_id] = itemsBy[i.bundle_id] || []).push(i); });
const reminded = new Set();
const flagged = new Set();
rows('Get Contact Log').forEach(d => {
  if (d.raw_text === "REMIND_1") reminded.add(d.bundle_id);
  if (d.raw_text === "STAFF_FLAGGED") flagged.add(d.bundle_id);
});
const dayStart = iso => new Date(String(iso).slice(0, 10) + "T00:00:00+02:00");
const ymd = d => new Date(d.getTime() + 2 * 3600000).toISOString().slice(0, 10);
const out = [];
for (const b of rows('Get Bundles')) {
  if (only.length && !only.includes(String(b.bundle_id))) continue;
  if (!["QUEUED", "SENT"].includes(b.status)) continue;
  const route = String(b.route || "").toUpperCase();
  let pubs = b.publishers;
  if (typeof pubs === "string") { try { pubs = JSON.parse(pubs); } catch (e) { pubs = []; } }
  pubs = Array.isArray(pubs) ? pubs : [];
  const main = pubs.filter(p => !BEST_EFFORT.includes(p.publisherId));
  const slowestSec = Math.max(0, ...main.map(p => Number(p.typicalUpdateSpeedSeconds) || 0));
  const leadDays = Math.ceil(slowestSec / 86400) + BUFFER_DAYS;
  const upcoming = (itemsBy[b.bundle_id] || []).map(i => i.date).filter(d => d && dayStart(d) > asOf).sort();
  let action = "NONE";
  let reason = null;
  let holiday = null, deadline = null, firstContact = null, remindAt = null;
  if (upcoming.length) {
    holiday = dayStart(upcoming[0]);
    deadline = new Date(holiday.getTime() - leadDays * DAY);
    firstContact = new Date(deadline.getTime() - FIRST_CONTACT_DAYS * DAY);
  }
  if (b.status === "QUEUED") {
    if (route === "STAFF") {
      // A business that looks closed for good goes to Connect staff at once, once.
      if (flagged.has(b.bundle_id)) reason = "STAFF_ALREADY_FLAGGED";
      else { action = "INITIAL"; reason = "STAFF_NOW"; }
    } else if (!holiday) reason = "NO_UPCOMING_DATES";
    else if (asOf >= firstContact) { action = "INITIAL"; reason = asOf > deadline ? "LATE_FIRST_CONTACT" : "FIRST_CONTACT_DUE"; }
    else reason = "WAIT_UNTIL " + ymd(firstContact);
  } else {
    const sentAt = new Date(b.updated_at || b.created_at);
    if (!["SUGGEST", "ASK"].includes(route)) reason = "NO_REMINDER_FOR_" + route;
    else if (reminded.has(b.bundle_id)) reason = "ALREADY_REMINDED";
    else if (b.opted_out === true || !b.telegram_chat_id) reason = "NOT_CONTACTABLE";
    else if (!holiday) reason = "NO_UPCOMING_DATES";
    else {
      // Whole days: the scheduler runs once a day, so the reminder is due from the start of that day.
      remindAt = dayStart(ymd(new Date(Math.max(sentAt.getTime() + DAY,
        Math.min(sentAt.getTime() + REMIND_AFTER_DAYS * DAY, deadline.getTime() - REMIND_LATEST_DAYS * DAY)))));
      if (asOf >= remindAt) { action = "REMIND"; reason = "NO_REPLY_SINCE " + ymd(sentAt); }
      else reason = "REMIND_FROM " + ymd(remindAt);
    }
  }
  out.push({ json: {
    bundle_id: b.bundle_id, business_name: b.business_name, route, status: b.status, action, reason,
    next_holiday: holiday ? upcoming[0] : null, deadline: deadline ? ymd(deadline) : null,
    first_contact: firstContact ? ymd(firstContact) : null, remind_at: remindAt ? ymd(remindAt) : null,
    lead_days: leadDays, language: b.language, telegram_chat_id: b.telegram_chat_id,
    opted_out: b.opted_out === true, intro_text: b.intro_text || "",
  } });
}
return out;

const cfg = $('Config').first().json;
const rows = $input.all().map(i => i.json);
const per_action = {};
rows.forEach(r => { per_action[r.action] = (per_action[r.action] || 0) + 1; });
return [{ json: {
  dry_run: true,
  as_of: cfg.as_of,
  total: rows.length,
  per_action,
  planned: rows.filter(r => r.action !== "NONE").map(r => ({ bundle_id: r.bundle_id, action: r.action, reason: r.reason, deadline: r.deadline })),
  bundles: rows.map(r => ({ bundle_id: r.bundle_id, route: r.route, status: r.status, action: r.action, reason: r.reason,
    next_holiday: r.next_holiday, deadline: r.deadline, first_contact: r.first_contact, remind_at: r.remind_at })),
} }];

const b = $json;
const lang = ["fi", "sv", "nb", "en"].includes(b.language) ? b.language : "en";
const d = String(b.deadline || "").split("-");
const label = d.length === 3
  ? (lang === "en" ? Number(d[2]) + " " + ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][Number(d[1]) - 1]
    : lang === "sv" ? Number(d[2]) + "/" + Number(d[1]) : Number(d[2]) + "." + Number(d[1]) + ".")
  : "";
const PREFIX = {
  fi: "🔔 Muistutus: vastaathan viimeistään " + label + ", jotta ajat ehtivät kaikkiin palveluihin.",
  sv: "🔔 Påminnelse: svara senast " + label + " så att tiderna hinner ut i alla tjänster.",
  nb: "🔔 Påminnelse: svar innen " + label + " så tidene rekker ut i alle tjenester.",
  en: "🔔 Reminder: please reply by " + label + " so the hours reach every channel in time.",
};
const id = b.bundle_id;
// Same three buttons as the first message (Step 3 Intro Payload), so the router handles them as usual.
const buttons = b.route === "ASK"
  ? [{ key: "btn_closed", data: "qc:" + id }, { key: "btn_regular", data: "qr:" + id }, { key: "btn_edit", data: "e:" + id }]
  : [{ key: "btn_approve", data: "a:" + id }, { key: "btn_edit", data: "e:" + id }, { key: "btn_decline", data: "d:" + id }];
return { json: {
  bundle_id: id,
  chat_id: String(b.telegram_chat_id),
  language: lang,
  text: PREFIX[lang] + "\n\n" + b.intro_text,
  key: null,
  params: {},
  lines: [],
  buttons,
  edit_message_id: null,
} };
